#include "i8042.hpp"
#include <chrono>
#include <climits>
#include <iostream>
#include <stdexcept>
#include <string_view>
using namespace pc;
static bool reference(const PS2Mouse &m,uint64_t now) {
    return m.enabled && !m.remote && !m.wrap && m.packets.empty() && now>=m.nextAt &&
           (m.dx||m.dy||m.wheel||m.buttons!=m.reportedButtons);
}
int main(int argc,char **argv) {
    PS2Mouse m;unsigned checks=0;
    for(unsigned flags=0;flags<16;++flags) {
        m.enabled=flags&1;m.remote=flags&2;m.wrap=flags&4;
        m.packets.clear();if(flags&8)m.packets.push_back(8);
        for(int dx:{0,1,-1,INT_MIN,INT_MAX})for(int dy:{0,1,-1,INT_MIN,INT_MAX})
        for(int wheel:{0,1,-1,INT_MIN,INT_MAX})for(unsigned buttons:{0u,1u,7u,255u})
        for(unsigned reported:{0u,1u,7u,255u})for(uint64_t deadline:std::array<uint64_t,3>{0,4000,UINT64_MAX})
        for(uint64_t now:std::array<uint64_t,5>{0,3999,4000,4001,UINT64_MAX}) {
            m.dx=dx;m.dy=dy;m.wheel=wheel;m.buttons=buttons;m.reportedButtons=reported;m.nextAt=deadline;
            if(m.packetDue(now)!=reference(m,now))throw std::runtime_error("mouse sample predicate differs");
            ++checks;
        }
    }
    std::cout<<"Passed "<<checks<<" packet deadline comparisons\n";
    if(argc>1 && std::string_view(argv[1])=="--bench") {
        I8042Device c;
        for(bool enabled:{false,true}) {
            c.mouse().enabled=enabled;
            auto begin=std::chrono::steady_clock::now();uint64_t due=0;
            for(uint64_t now=0;now<100000000;++now) {
                // Model a separate JIT/board call that can mutate live state;
                // prevent constant folding the idle fixture out of the loop.
                asm volatile("" : "+m"(c) : : "memory");
                due+=c.pollDue(now);
            }
            if(due)throw std::runtime_error("idle controller unexpectedly due");
            auto ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();
            std::cout<<"enabled="<<enabled<<" polls=100000000 ms="<<ms<<" due="<<due<<'\n';
        }
    }
}

